    public static byte[] decompressZerocoded(byte[] src) {
        ByteBuffer dest = ByteBuffer.allocate(src.length * 4);
        int i = 0;
        while (i < src.length) {
            byte b = src[i];
            if (b == 0) {
                if (i + 1 < src.length) {
                    int count = src[i + 1] & 0xFF;
                    if (count == 0) {
                        dest.put((byte) 0);
                        i += 2;
                    } else {
                        for (int k = 0; k < count; k++) {
                            dest.put((byte) 0);
                        }
                        i += 2;
                    }
                } else {
                    dest.put((byte) 0);
                    i++;
                }
            } else {
                dest.put(b);
                i++;
            }
        }
        byte[] result = new byte[dest.position()];
        dest.flip();
        dest.get(result);
        return result;
    }
